begin;
create extension if not exists pgcrypto;

create table if not exists public."ajvs_category" (
  "id" bigint generated by default as identity primary key,
  "name_en" varchar(80) not null,
  "name_ta" varchar(80) not null,
  "slug" varchar(80) not null,
  "sort_order" bigint not null,
  "is_active" boolean not null,
  "art" varchar(10) not null,
  "is_combo" boolean not null,
  "tagline_en" varchar(160) not null,
  "tagline_ta" varchar(160) not null,
  "theme" varchar(10) not null,
  "image" varchar(100),
  check ("sort_order" >= 0),
  unique ("slug")
);

create table if not exists public."ajvs_contact_message" (
  "id" bigint generated by default as identity primary key,
  "name" varchar(100) not null,
  "phone" varchar(15) not null,
  "message" text not null,
  "is_read" boolean not null,
  "created_at" timestamptz not null,
  "email" varchar(254) not null,
  "reason" varchar(20) not null
);

create table if not exists public."ajvs_coupon" (
  "id" bigint generated by default as identity primary key,
  "code" varchar(30) not null,
  "description_en" varchar(150) not null,
  "description_ta" varchar(150) not null,
  "kind" varchar(10) not null,
  "value" numeric not null,
  "max_discount" numeric,
  "min_order" numeric not null,
  "valid_from" date,
  "valid_until" date,
  "usage_limit" bigint,
  "once_per_phone" boolean not null,
  "used_count" bigint not null,
  "is_active" boolean not null,
  "created_at" timestamptz not null,
  check ("usage_limit" >= 0),
  check ("used_count" >= 0),
  unique ("code")
);

create table if not exists public."ajvs_delivery_area" (
  "id" bigint generated by default as identity primary key,
  "name_en" varchar(100) not null,
  "name_ta" varchar(100) not null,
  "delivery_fee" numeric not null,
  "is_active" boolean not null,
  "sort_order" bigint not null,
  check ("sort_order" >= 0)
);

create table if not exists public."ajvs_dish" (
  "id" bigint generated by default as identity primary key,
  "name_en" varchar(120) not null,
  "name_ta" varchar(120) not null,
  "description_en" varchar(300) not null,
  "description_ta" varchar(300) not null,
  "price" numeric not null,
  "image" varchar(100),
  "is_veg" boolean not null,
  "is_available" boolean not null,
  "is_special" boolean not null,
  "meal_slot" varchar(10) not null,
  "sort_order" bigint not null,
  "created_at" timestamptz not null,
  "updated_at" timestamptz not null,
  "category_id" bigint not null,
  "art" varchar(10) not null,
  "badge" varchar(12) not null,
  "compare_price" numeric,
  "details_en" text not null,
  "details_ta" text not null,
  "spice_level" smallint not null,
  "sunday_only" boolean not null,
  check ("sort_order" >= 0),
  check ("spice_level" >= 0),
  foreign key ("category_id") references "ajvs_category" ("id")
);

create table if not exists public."ajvs_menu_subscriber" (
  "id" bigint generated by default as identity primary key,
  "phone" varchar(10) not null,
  "language" varchar(2) not null,
  "is_active" boolean not null,
  "created_at" timestamptz not null,
  unique ("phone")
);

create table if not exists public."ajvs_order" (
  "id" bigint generated by default as identity primary key,
  "order_number" varchar(20) not null,
  "token" char(32) not null,
  "customer_name" varchar(100) not null,
  "phone" varchar(15) not null,
  "email" varchar(254) not null,
  "address" text not null,
  "landmark" varchar(150) not null,
  "delivery_area_name" varchar(100) not null,
  "notes" varchar(300) not null,
  "subtotal" numeric not null,
  "delivery_fee" numeric not null,
  "total" numeric not null,
  "status" varchar(20) not null,
  "razorpay_order_id" varchar(60) not null,
  "razorpay_payment_id" varchar(60) not null,
  "razorpay_signature" varchar(200) not null,
  "paid_at" timestamptz,
  "language" varchar(2) not null,
  "created_at" timestamptz not null,
  "updated_at" timestamptz not null,
  "delivery_area_id" bigint,
  "address_label" varchar(30) not null,
  "building" varchar(150) not null,
  "coupon_code" varchar(30) not null,
  "delivery_date" date,
  "delivery_slot" varchar(20) not null,
  "discount" numeric not null,
  "fulfilment" varchar(10) not null,
  "is_advance" boolean not null,
  "latitude" numeric,
  "location_accuracy" bigint,
  "longitude" numeric,
  "no_cutlery" boolean not null,
  check ("location_accuracy" >= 0),
  foreign key ("delivery_area_id") references "ajvs_delivery_area" ("id"),
  unique ("token"),
  unique ("order_number")
);

create table if not exists public."ajvs_order_item" (
  "id" bigint generated by default as identity primary key,
  "dish_name" varchar(120) not null,
  "unit_price" numeric not null,
  "quantity" bigint not null,
  "line_total" numeric not null,
  "dish_id" bigint,
  "order_id" bigint not null,
  check ("quantity" >= 0),
  foreign key ("order_id") references "ajvs_order" ("id"),
  foreign key ("dish_id") references "ajvs_dish" ("id")
);

create table if not exists public."ajvs_policy_page" (
  "id" bigint generated by default as identity primary key,
  "slug" varchar(30) not null,
  "title_en" varchar(120) not null,
  "title_ta" varchar(120) not null,
  "body_en" text not null,
  "body_ta" text not null,
  "updated_at" timestamptz not null,
  unique ("slug")
);

create table if not exists public."ajvs_site_settings" (
  "id" bigint generated by default as identity primary key,
  "kitchen_open" boolean not null,
  "closed_message_en" varchar(200) not null,
  "closed_message_ta" varchar(200) not null,
  "order_hours_en" varchar(200) not null,
  "order_hours_ta" varchar(200) not null,
  "phone" varchar(20) not null,
  "whatsapp" varchar(20) not null,
  "email" varchar(254) not null,
  "address_en" text not null,
  "address_ta" text not null,
  "map_embed_url" varchar(600) not null,
  "fssai_number" varchar(20) not null,
  "instagram_url" varchar(200) not null,
  "min_order_amount" numeric not null,
  "free_delivery_above" numeric not null,
  "updated_at" timestamptz not null,
  "swiggy_url" varchar(400) not null,
  "zomato_url" varchar(400) not null,
  "alert_email" varchar(254) not null,
  "whatsapp_alert_token" varchar(200) not null,
  "whatsapp_alert_url" varchar(400) not null,
  "advance_max_days" smallint not null,
  "advance_min_days" smallint not null,
  "delivery_charge" numeric not null,
  "delivery_radius_km" smallint not null,
  "kitchen_lat" numeric not null,
  "kitchen_lng" numeric not null,
  "order_end" time without time zone not null,
  "order_start" time without time zone not null,
  "google_maps_key" varchar(100) not null,
  check ("advance_max_days" >= 0),
  check ("advance_min_days" >= 0),
  check ("delivery_radius_km" >= 0)
);

create or replace function public.set_updated_at()
returns trigger language plpgsql
as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

drop trigger if exists trg_ajvs_dish_updated_at on public."ajvs_dish";
create trigger trg_ajvs_dish_updated_at before update on public."ajvs_dish" for each row execute function public.set_updated_at();
drop trigger if exists trg_ajvs_order_updated_at on public."ajvs_order";
create trigger trg_ajvs_order_updated_at before update on public."ajvs_order" for each row execute function public.set_updated_at();
drop trigger if exists trg_ajvs_site_settings_updated_at on public."ajvs_site_settings";
create trigger trg_ajvs_site_settings_updated_at before update on public."ajvs_site_settings" for each row execute function public.set_updated_at();

alter table public."ajvs_category" enable row level security;
alter table public."ajvs_contact_message" enable row level security;
alter table public."ajvs_coupon" enable row level security;
alter table public."ajvs_delivery_area" enable row level security;
alter table public."ajvs_dish" enable row level security;
alter table public."ajvs_menu_subscriber" enable row level security;
alter table public."ajvs_order" enable row level security;
alter table public."ajvs_order_item" enable row level security;
alter table public."ajvs_policy_page" enable row level security;
alter table public."ajvs_site_settings" enable row level security;

drop policy if exists "ajvs_category_public_read" on public."ajvs_category";
create policy "ajvs_category_public_read" on public."ajvs_category" for select to anon, authenticated using (is_active = true);
drop policy if exists "ajvs_dish_public_read" on public."ajvs_dish";
create policy "ajvs_dish_public_read" on public."ajvs_dish" for select to anon, authenticated using (is_available = true);
drop policy if exists "ajvs_delivery_area_public_read" on public."ajvs_delivery_area";
create policy "ajvs_delivery_area_public_read" on public."ajvs_delivery_area" for select to anon, authenticated using (is_active = true);
drop policy if exists "ajvs_policy_page_public_read" on public."ajvs_policy_page";
create policy "ajvs_policy_page_public_read" on public."ajvs_policy_page" for select to anon, authenticated using (true);

